CREATE OR REPLACE FUNCTION private.base_config() RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT private.org_role_previous_config()||jsonb_build_object('role_links',c->'role_links','memberships',c->'memberships','units',c->'units','titles',c->'titles') FROM (SELECT private.org_config() c OFFSET 0) snapshot $$;
DO $$ DECLARE d text;BEGIN SELECT pg_get_functiondef('private.base_effective(uuid,jsonb)'::regprocedure) INTO d;d:=replace(d,$s$private.base_decision(u,r.key,c)$s$,$s$CASE WHEN EXISTS(SELECT 1 FROM jsonb_array_elements(rules) x WHERE x->>'permission'=r.key AND x->>'effect'='DENY') THEN 'DENY' WHEN EXISTS(SELECT 1 FROM jsonb_array_elements(rules) x WHERE x->>'permission'=r.key AND x->>'effect'='ALLOW') THEN 'ALLOW' ELSE 'NOT_CONFIGURED' END$s$);EXECUTE d;END $$;